GATTA_KUSTHI_BANGLA_BEATS: List[Tuple[str, str]] = [
    ("hook", "সিনেমার শুরুতে আমাদের পরিচয় করিয়ে দেওয়া হয় সমাজের এক চরম ও নির্মম বাস্তবতার সাথে। আমাদের এই তথাকথিত পুরুষতান্ত্রিক সমাজে অধিকাংশ পুরুষই মনে মনে চায় তার স্ত্রী যেন সবসময় তার চেয়ে এক ধাপ নিচে থাকে, তার প্রতিটি কথা মুখ বুজে মেনে নেয় এবং কখনো কোনো প্রতিবাদ না করে। কিন্তু ভাগ্যের নির্মম পরিহাসে এমন এক অহংকারী পুরুষের সাথে যদি এমন এক দুর্ধর্ষ নারী রেসলারের বিয়ে হয়ে যায়, যে একা হাতে এক ডজন সশস্ত্র গুন্ডাকে ধুলো খাইয়ে দিতে পারে, তবে সেই সংসারের রূপ কেমন হবে?"),
    ("hook", "দৃশ্যপট শুরু হয় মনোরম কেরালা ও তামিলনাড়ুর সীমান্তবর্তী এক ঐতিহ্যবাহী কুস্তির ময়দান থেকে। মাটির আখড়ায় চলছে ঐতিহ্যবাহী গাট্টা কুস্তির এক শ্বাসরুদ্ধকর ও রোমাঞ্চকর টুর্নামেন্ট। সেখানে বিদ্যুৎগতির মুভমেন্ট, নিখুঁত টেকনিক্যাল লক আর অসম্ভব শারীরিক শক্তি দিয়ে একের পর এক অভিজ্ঞ কুস্তিগীরকে রিংয়ের মেঝেতে আছাড় মেরে ধুলো খাইয়ে জয়ী হয় আমাদের গল্পের মূল নায়িকা—সাহসী তরুণী কীর্তি! চারদিকের উল্লাসের মাঝে গ্যালারিতে থাকা তার মামা গণেশন আনন্দে আত্মহারা হয়ে নাচতে শুরু করে।"),
    ("hook", "কিন্তু ঘরের চার দেয়ালে ফিরতেই আনন্দের আলো এক লহমায় ম্লান হয়ে যায়। কীর্তির বাবা মেয়ের এই কুস্তি খেলা চরম অপছন্দ করেন। তার বক্তব্য সোজা—মেয়ের বয়স বাড়ছে, এই কুস্তিগীর মেয়েকে কোনো ভদ্র পরিবার মেনে নেবে না! উপরন্তু যেসব পাত্রপক্ষ বিয়ের প্রস্তাব নিয়ে এসে খোলাখুলি মোটা অঙ্কের যৌতুক দাবি করে, আত্মমর্যাদাসম্পন্ন কীর্তি এক মুহূর্তও দেরি না করে সোজা তাদের বাড়ি থেকে ঘাড় ধাক্কা দিয়ে বের করে দেয়। ফলে বেচারা মামা গণেশন ভাগ্নির বিয়ে নিয়ে চরম মানসিক ডিপ্রেশনে পড়ে যান।"),
    ("hook", "ভাগ্নিকে সামাজিক অপবাদের হাত থেকে রক্ষা করতে এবং একটা ভালো ঘরে শান্তিতে তুলে দিতে মামা গণেশন মরিয়া হয়ে ওঠেন। তিনি মনে মনে দৃঢ় প্রতিজ্ঞা করেন—এমন এক বর তাকে খুঁজে বের করতেই হবে, যে কোনো যৌতুক দাবি করবে না এবং কীর্তিকে স্ত্রীর পূর্ণ মর্যাদা ও ভালোবাসা দেবে। কিন্তু প্রচলিত নিয়মে কীর্তির এই সাহসী রেসলার পরিচয় জানলে কোনো পাত্রই বিয়ের পিঁড়িতে বসবে না, তাই বাধ্য হয়ে গণেশন এক অসম্ভব নাটকের পরিকল্পনা করেন।"),

    ("setup", "এবার ক্যামেরা ঘুরে যায় তামিলনাড়ুর এক শান্ত ও সবুজ জনপদে। পরিচয় ঘটে আমাদের ছবির নায়ক বীরার সাথে। বাপের রেখে যাওয়া বিপুল পৈতৃক জমিজমার মালিক বীরা সারাদিন কোনো কাজকর্ম না করে বন্ধুদের সাথে চায়ের দোকানে বসে আড্ডা আর তাস পিটিয়ে আয়েশে সময় কাটায়। নিজে কোনো কাজ না করলেও এবং পড়াশোনায় টেনেটুনে মাত্র ক্লাস এইট পাস হওয়া সত্ত্বেও বীরার অহংকার আর পুরুষালী ভাব ছিল আসমান সমান উঁচু!"),
    ("setup", "বীরার জীবনের সবচেয়ে বড় ও একমাত্র স্বপ্ন হলো বিয়ে করা, তবে তার রয়েছে তিনটি আজব ও হাস্যকর শর্ত। প্রথমত, পাত্রীকে অবশ্যই ক্লাস এইটের নিচে পড়াশোনা জানা হতে হবে, যাতে বীরা তার ওপর আজীবন খবরদারি করতে পারে। দ্বিতীয়ত, মেয়ের মাথায় থাকতে হবে একঢাল কালো লম্বা চুল। আর তৃতীয়ত, বউকে হতে হবে এমন এক শান্ত ও অনুগত পুতুল—যে স্বামীর কোনো হুকুম বা সিদ্ধান্তে কখনোই নিজের টু শব্দটিও করবে না!"),
    ("setup", "বীরার এই পুরুষতান্ত্রিক অন্ধ অহংকারকে সারাক্ষণ বাতাস দিয়ে উসকে দেয় তার ধান্দাবাজ ও ধূর্ত চাচা রত্নম। এই রত্নম নিজে কোনো কাজকাম করে না, সারাদিন বীরার পয়সায় আয়েশ করে খায় এবং তাকে নানা ভুলভাল বুদ্ধি দিয়ে নিজের হাতের পুতুল বানিয়ে রাখে। রত্নম ভালো করেই জানে যে পরিবারে যদি বীরার বউ শক্তিশালী হয়ে ওঠে, তবে তার নিজের মাতব্বরি আর পরজীবী জীবনযাত্রা চিরতরে বন্ধ হয়ে যাবে।"),
    ("setup", "এদিকে বিয়ের ভালো পাত্রের সন্ধানে তামিলনাড়ুর গ্রামে এসে ঘটনাক্রমে রত্নমের সাথে দেখা হয়ে যায় কীর্তির মামা গণেশনের। রত্নম বুক ফুলিয়ে দম্ভভরে জানায় তার ভাতিজা কোটি টাকার জমিদার এবং সে কোনো যৌতুক বা পণ ছাড়াই বিয়ে করতে প্রস্তুত। বিনা পণে কোটিপতি পাত্রের কথা শুনে গণেশনের কান খাড়া হয়ে যায়! সে মনে মনে ভাবে, এমন সুবর্ণ সুযোগ জীবনে আর দ্বিতীয়বার আসবে না, যেকোনো মূল্যে এই বিয়ে পাকা করতেই হবে।"),
    ("setup", "বীরাকে রাজি করাতে গণেশন এক চরম চালাকির আশ্রয় নেয়। কেরালায় ফিরে বাবার শারীরিক অসুস্থতা আর সামাজিক সম্মানের দোহাই দিয়ে সে কীর্তিকে এক দিনের জন্য মিথ্যা অভিনয়ের অনুরোধ করে। বাজার থেকে কেনা হয় কোমর পর্যন্ত লম্বা নকল চুলের উইগ, পরানো হয় লাল শাড়ি। মামা তাকে কড়া রিহার্সাল করায়—বীরার সামনে চোখ তুলে তাকানো চলবে না, শুধু লাজুক ভঙ্গিতে মুখ নিচু করে দাঁড়িয়ে থাকতে হবে।"),
    ("setup", "দলবল নিয়ে মেয়ে দেখতে কনের বাড়িতে সশরীরে হাজির হয় বীরা ও রত্নম। ট্রে হাতে ধীরপায়ে ড্রয়িংরুমে প্রবেশ করে লাল শাড়িতে ঢাকা দীর্ঘ চুলের লাজুক কীর্তি। মাথা নিচু করা সেই শান্ত প্রতিমা দেখে বীরা তো প্রথম দর্শনেই পুরোপুরি ক্লিন বোল্ড হয়ে যায়! বীরা প্রশ্ন করে পড়াশোনা কতদূর, মামা সাথে সাথে বানিয়ে বলে—ক্লাস সেভেনের পরই স্কুল ছেড়েছে! বীরা তো মহাখুশি হয়ে তখনই বিয়ের চূড়ান্ত সিদ্ধান্ত জানিয়ে দেয়।"),
    ("setup", "কোনো যৌতুক না চাওয়ার কারণে বীরার প্রতি কীর্তির মনেও কিছুটা শ্রদ্ধাবোধ ও ভালো লাগা তৈরি হয়। সে ভাবে বীরা হয়তো সমাজের আর পাঁচটা লোভী পুরুষের মতো নয়, বরং একজন সৎ মনের মানুষ। বাবার মুখে বহু বছর পর স্বস্তির হাসি দেখে এবং পরিবারের মান বাঁচাতে কীর্তি সমস্ত দ্বিধা দূরে ঠেলে বিয়ের পিঁড়িতে বসে। চারদিকে বাদ্য বাজিয়ে অতি ধুমধাম করে বীরার সাথে কীর্তির শুভ বিবাহ সম্পন্ন হয়।"),

    ("inciting_incident", "বিয়ের পর কীর্তি নতুন বউ হয়ে পা রাখে বীরার গ্রামের বাড়িতে। বাসর রাতেই নিজের পুরুষালী দাপট আর কর্তৃত্ব কায়েম করতে বীরা বুক ফুলিয়ে গম্ভীর গলায় ঘোষণা দেয়—এই বাড়িতে শুধু আমার হুকুম চলবে, আমার মতের বাইরে এখানে একটি গাছের পাতাও নড়বে না! কীর্তি নীরবে মাথা নিচু করে সব আদেশ শুনে যায়। বীরা তো মনে মনে পরম তৃপ্তি পায় যে সে এক শান্ত হরিণীকে বশ করে ফেলেছে!"),
    ("inciting_incident", "শ্বশুরবাড়িতে শুরু হয় কীর্তির চরম দমবন্ধ করা এক দ্বৈত জীবন। প্রতিদিন ভোরে সবার আগে উঠে লুকিয়ে মাথায় নকল উইগ সেট করতে হয়, যাতে ছোট ছাঁটা চুল কেউ দেখে না ফেলে। যে মেয়ে ময়দানে টনকে টন ওজন নিয়ে কুস্তির লড়াই করত, সে এখন রান্নাঘরে অলস বসে থাকে। সুযোগ পেলেই রাতের আঁধারে রান্নাঘরের চালের ভারী বস্তা দিয়ে সে গোপনে ওয়েটলিফটিং করে নিজের দম আর ফিটনেস ধরে রাখে।"),
    ("inciting_incident", "এদিকে বীরার সাজানো পারিবারিক জীবনে হঠাৎ ঘনিয়ে আসে এক কালো অমাবস্যা। গ্রামের প্রভাবশালী রাজনৈতিক নেতা ও স্থানীয় ত্রাস মাফিয়া দাস বীরার একখণ্ড অতি মূল্যবান পৈতৃক জমির ওপর নজর দেয়। দাস জমিটি জোর করে নামমাত্র মূল্যে লিখে নিতে চাইলে অলস বীরা নিজের পরিবারের একমাত্র সম্বল পৈতৃক জমি ছাড়তে সাফ অস্বীকৃতি জানায়। শুরু হয় গ্রামের মাতব্বরদের সামনে এক উত্তপ্ত বিরোধ।"),
    ("inciting_incident", "অপমানিত হয়ে মাফিয়া দাস বীরাকে শায়েস্তা করার এক জঘন্য নোংরা ষড়যন্ত্রে নামে। সে পুলিশের দুর্নীতিগ্রস্ত বড় কর্তাদের হাত করে বীরার একমাত্র অভিভাবক চাচা রত্নমকে এক মিথ্যা মামলায় ফাঁসিয়ে সোজা জেলে পুরে দেয়। এরপর দাস প্রকাশ্য দিবালোকে বীরার বাড়িতে দলবল নিয়ে এসে হুমকি দেয়—জমি লিখে না দিলে বীরা ও তার নতুন বউয়ের লাশ গ্রামের খালে ভাসিয়ে দেওয়া হবে!"),
    ("inciting_incident", "চাচা জেলে বন্দি আর চোখের সামনে মাফিয়ার এমন প্রকাশ্য মরণ হুমকি দেখে সাধারণ অলস যুবক বীরা মানসিকভাবে পুরোপুরি ভেঙে পড়ে। বীরার চোখেমুখে এক গভীর অসহায়তা ও আতঙ্কের ছাপ স্পষ্ট হয়ে ওঠে। কীর্তি তার স্বামীর এই চরম ভয় ও মানসিক অস্থিরতা নীরবে পর্যবেক্ষণ করতে থাকে, কিন্তু পরিবারের শান্তি ও সামাজিক বাঁধনের কথা ভেবে সে তখনো নিজের শক্তি প্রকাশ করে না।"),

    ("investigation", "পরিস্থিতির চরম মানসিক চাপ সামলাতে ও ঈশ্বরের আশীর্বাদ নিতে বীরা তার স্ত্রী কীর্তিকে নিয়ে গ্রামের এক নির্জন পাহাড়ি মন্দিরে পুজো দেওয়ার সিদ্ধান্ত নেয়। বীরা ভেবেছিল নির্জন পাহাড়ে অন্তত কোনো বিপদ হবে না, কিন্তু চতুর দাস আগে থেকেই সেখানে বীরার গতিবিধির ওপর কড়া নজর রাখছিল। এটি ছিল মাফিয়া দাসের পাতা এক সুপরিকল্পিত ও নারকীয় মরণফাঁদ।"),
    ("investigation", "মন্দির চত্বরে বীরার গাড়ি থামতেই হঠাৎ কোথা থেকে লাঠি, লোহার রড আর ধারালো অস্ত্র হাতে প্রায় কুড়িজন সশস্ত্র ভাড়াটে গুন্ডা এসে বীরা ও কীর্তিকে চারপাশ থেকে ঘিরে ফেলে। কালো কাঁচের জিপ থেকে নেমে আসে স্বয়ং মাফিয়া দাস। সে ব্যঙ্গ করে হাসতে হাসতে বলে—জমি লিখে দেওয়ার এই তোর শেষ সুযোগ, নইলে আজ এই মন্দিরের সিঁড়িতেই তোদের রক্তে মাটি লাল হবে!"),
    ("investigation", "বীরা সাহস সঞ্চয় করে বাধা দিতে গেলে গুন্ডারা দল বেঁধে একযোগে তার ওপর ঝাঁপিয়ে পড়ে। লাঠি আর লোহার রডের এলোপাতাড়ি আঘাতে বীরা রক্তাক্ত হয়ে মন্দিরের পাথুরে চত্বরে লুটিয়ে পড়ে। বীরা যন্ত্রণায় কাতরাচ্ছে, আর গুন্ডারা তাকে বুট দিয়ে মাটির সাথে পিষে ফেলতে শুরু করে। মাফিয়া দাস হিংস্র পশুর মতো অট্টহাসি হেসে বীরার মৃত্যু উপভোগ করতে থাকে।"),
    ("investigation", "স্বামীর এই রক্তাক্ত ও অসহায় দৃশ্য দেখে মন্দিরের সিঁড়িতে দাঁড়িয়ে থাকা কীর্তির ধৈর্যের শেষ বাঁধ এক নিমেষে ভেঙে চুরমার হয়ে যায়! তার চোখের মণি হিংস্র বাঘিনীর মতো জ্বলে ওঠে। মাথার নকল উইগটা একটু শক্ত করে চেপে কীর্তি নিজের শাড়ির আঁচলটা দৃঢ়ভাবে কোমরে পেঁচিয়ে বাঁধে। কোনো ভয় বা দ্বিধা না রেখে সে ধীর ও শিকারী পদক্ষেপে গুন্ডা বাহিনীর দিকে এগিয়ে আসে।"),
    ("investigation", "এক গুন্ডা তাচ্ছিল্যভরে কীর্তিকে ধাক্কা মারতে হাত বাড়াতেই কীর্তি এক সেকেন্ডে তার কবজি খপ করে ধরে ফেলে। চোখের পলকে শরীর ঘুরিয়ে সে গুন্ডাটিকে শূন্যে তুলে এমন এক আছাড় দেয় যে পাথুরে চত্বর ফেটে ধুলো উড়ে যায়! শুরু হয় এক অবিশ্বাস্য, রোমহর্ষক ও রক্ত গরম করা মারপিট—যা দেখে বীরা রক্তমাখা মুখ তুলে হতভম্ব হয়ে অপলক দৃষ্টিতে তাকিয়ে থাকে!"),
    ("investigation", "কীর্তি এবার একের পর এক প্রফেশনাল গাট্টা কুস্তির বিধ্বংসী সব প্যাঁচ চালাতে শুরু করে। কাউকে পা ধরে বাতাসে ঘুরিয়ে দশ হাত দূরে পাথরের ওপর আছড়ে ফেলছে, কাউকে এক ঝটকায় কাঁধে তুলে মেরুদণ্ড ভেঙে দিচ্ছে। মুহূর্তের মধ্যে মন্দিরের পবিত্র চত্বর গুন্ডাদের হাড়গোড় ভাঙার শব্দ আর যন্ত্রণার আর্তনাদে প্রকম্পিত হয়ে ওঠে। কুড়িজন সশস্ত্র পুরুষকে একা এক নারী পিটিয়ে মাটির সাথে মিশিয়ে দেয়!"),
    ("investigation", "সবশেষে কীর্তি ধীরপায়ে এগিয়ে যায় মূল মাফিয়া দাসের দিকে। দাস তখন ভয়ে থরথর করে কাঁপতে কাঁপতে পেছাতে থাকে। কীর্তি এক হাতে দাসের কলার চেপে ধরে শূন্যে তুলে মাটিতে আছড়ে ফেলে এবং দাসের বুকের ওপর নিজের ভারী বুট চেপে ধরে বরফের মতো শীতল গলায় হুঁশিয়ারি দেয়—আজকের পর আমার স্বামীর দিকে বাঁকা চোখে তাকালে তোকে এই মাটিতেই জীবন্ত পুঁতে ফেলব! দাস প্রাণভয়ে সেখান থেকে পালিয়ে যায়।"),
    ("investigation", "রক্তাক্ত বীরা মাটিতে বসে হতভম্ব হয়ে দেখছে—যে বউকে সে ভেবেছিল সামান্য উচ্চবাচ্যও করতে জানে না, সে আসলে আস্ত এক জীবন্ত অ্যাকশন হিরো! পুরো গ্রামে এই অবিশ্বাস্য খবর দাবানলের মতো ছড়িয়ে পড়তেই তোলপাড় শুরু হয়। গ্রামের মহিলারা কীর্তিকে শ্রদ্ধায় ভাসিয়ে দেয়, আর বীরার বন্ধুরা বীরার দিকে তাকিয়ে ব্যঙ্গ ও তাচ্ছিল্যের হাসি হাসতে শুরু করে।"),

    ("escalation", "মন্দিরের সেই ঐতিহাসিক মারপিটের পর বীরার পুরুষালী অহংকার চূর্ণ হয়ে সেখানে চরম ভয়ের এক হাস্যকর রাজত্ব কায়েম হয়। ঘরে ফিরে বীরা কীর্তিকে দেখলে ভয়ে থরথর করে কাঁপতে থাকে। যে বউকে সে কথায় কথায় ধমক দিত, এখন সেই বউ ঘরে ঢুকলেই বীরা হাত জোড় করে বিনয়ের অবতার হয়ে দাঁড়িয়ে থাকে। কীর্তি সামান্য জোর গলায় কিছু বললেই বীরা মনে করে তাকে বুঝি এখনই কুস্তির প্যাঁচে আছাড় মারা হবে!"),
    ("escalation", "রাতে বিছানায় ঘুমানোর সময় বীরার অবস্থা হয় আরও বেশি করুণ ও হাস্যকর। সে খাটের একদম কিনারে দেওয়াল ঘেঁষে কাঁপতে কাঁপতে শুয়ে থাকে। ঘুমের ঘোরেও যদি তার কোনো হাত বা পা কীর্তির শরীরে লেগে যায় আর কীর্তি যদি ঘুমে ঘুমে কুস্তির কোনো লক মেরে হাত ভেঙে দেয়—এই কাল্পনিক আতঙ্কে বেচারা বীরার রাতের ঘুম পুরোপুরি উবে যায়!"),
    ("escalation", "কিন্তু পরিস্থিতির চরম অবনতি ঘটে যখন চালবাজ চাচা রত্নম জামিনে জেল থেকে বাড়ি ফিরে আসে। গ্রামে ফিরেই সে শুনতে পায় কীর্তি একাই সব গুন্ডাদের পিটিয়ে বীরাকে বাঁচিয়েছে এবং পুরো তল্লাটে এখন কেবল কীর্তিরই জয়জয়কার। এটি দেখে রত্নমের পুরুষতান্ত্রিক অহংকার চরম ধাক্কা খায়। সে বীরাকে উসকানি দিয়ে বিষ ঢালে—তুই একটা পৌরুষহীন দুর্বল ভীরু, বউয়ের আঁচলের তলায় মুখ লুকিয়ে আছিস!"),
    ("escalation", "রত্নম সরাসরি কীর্তির মুখোমুখি দাঁড়িয়ে অত্যন্ত কুৎসিত ও অশ্রাব্য ভাষায় তাকে আক্রমণ করতে শুরু করে। সে বলে—তুই এক পুরুষালী ডাইনি, মিথ্যার ভেক ধরে তুই আমাদের পারিবারিক মানসম্মান ধ্বংস করতে এসেছিস! তোকে এই বাড়িতে এক মুহূর্তও বরদাশত করা হবে না। কীর্তি নিজের আত্মসম্মান বজায় রেখে বারবার সংযম দেখায়, কিন্তু রত্নমের নোংরা ভাষা সমস্ত সীমা ছাড়িয়ে যায়।"),
    ("escalation", "ধৈর্যের শেষ সীমা অতিক্রম করতেই কীর্তি এক লহমায় এগিয়ে এসে রত্নমের গালে সজোরে এক চড় কষিয়ে দেয়! রত্নম ছিটকে মাটিতে পড়ে যায়। ঠিক সেই মুহূর্তে বাইরে থেকে ঘরে প্রবেশ করে বীরা। চাচাকে মাটিতে লুটিয়ে থাকতে দেখে বীরার পুরুষতান্ত্রিক অন্ধ অহংকার মুহূর্তে জ্বলে ওঠে। পেছনের কোনো সত্য না জেনেই ক্ষোভের বশে বীরা সজোরে কীর্তির গালে এক চড় মেরে বসে!"),
    ("escalation", "মুহূর্তের জন্য পুরো ঘরের বাতাস যেন জমাট বরফ হয়ে যায়। কীর্তি অপলক দৃষ্টিতে বীরার দিকে তাকায়। তার চোখে কোনো জল ছিল না, ছিল আত্মসম্মান ভূলুণ্ঠিত হওয়ার তীব্র যন্ত্রণা। কীর্তি তার মাথার নকল উইগটা খুলে মাটিতে ছুড়ে ফেলে দিয়ে বলে—যেখানে আমার সততা আর আত্মসম্মানের কোনো মূল্য নেই, সেখানে আমার থাকার কোনো প্রয়োজন নেই। নিজের ট্রলি ব্যাগ গুছিয়ে কীর্তি চিরদিনের মতো বাড়ি ছেড়ে চলে যায়।"),
    ("escalation", "কীর্তি বাবার বাড়ি ফিরে গেলে ধূর্ত রত্নম তার জীবনের সবচেয়ে বড় নোংরা চক্রান্তটি বাস্তবায়ন করে। সে বীরার অসচেতনতার সুযোগ নিয়ে বীরার সই জাল করে আদালতের মাধ্যমে কীর্তির ঠিকানায় আইনি ডিভোর্স নোটিশ পাঠিয়ে দেয়। নোটিশটি হাতে পেয়ে কীর্তি মানসিকভাবে পুরোপুরি ভেঙে পড়ে—সে কিছুতেই বিশ্বাস করতে পারে না যে বীরা সত্যিই তাকে এতটা ঘৃণা করে যে বিচ্ছেদ চেয়ে বসল!"),
    ("escalation", "কিন্তু কীর্তির বাবা এবার মেয়ের এই মানসিক ভাঙন আর সহ্য করতে পারেন না। তিনি মেয়ের হাত শক্ত করে ধরে বলেন—তুই কারও দয়া বা কৃপায় মাথা নিচু করে বেঁচে থাকার জন্য জন্মাসনি মা। তোর আসল পরিচয় তোর আত্মমর্যাদা আর কুস্তিতে। তুই আবার রিংয়ে ফিরে যা। বাবার অকুণ্ঠ অনুপ্রেরণায় কীর্তি চোখের জল মুছে ন্যাশনাল কুস্তি টুর্নামেন্টে লড়ার জন্য দিনরাত কঠোর অনুশীলন শুরু করে।"),
    ("escalation", "এদিকে রত্নম বীরাকেও শান্তি দেয় না। সে বীরাকে ক্রমাগত বিষবাষ্পে উসকে দিয়ে বলে—তোর বউ তোকে ছেড়ে গিয়ে পুরো সমাজে তোর মুখে চুনকালি দিয়েছে। তুই যদি সত্যিকারের বীরের সন্তান হোস, তবে তোকেও কুস্তি শিখতে হবে এবং ওই রিংয়ে নেমেই কীর্তিকে পিটিয়ে তোর পুরুষত্বের অপমানের বদলা নিতে হবে! অন্ধ আক্রোশে হিতাহিত জ্ঞান হারিয়ে বীরাও স্থানীয় কুস্তির আখড়ায় গিয়ে ভর্তি হয়।"),
    ("escalation", "আখড়ায় পা রেখেই বীরা জীবনের সবচেয়ে কঠিন ও কঠোর বাস্তবতার মুখোমুখি হয়। ওস্তাদজি যখন বীরাকে ডন-বৈঠক, কাদার মধ্যে কুস্তি আর দম বন্ধ করা ফিজিক্যাল ট্রেনিং দিতে শুরু করেন, কয়েক মিনিটেই বীরার সমস্ত হিরোগিরি খসে পড়ে। তার সারা শরীরে কালশিটে পড়ে যায়, পেশির অসহ্য ব্যথায় রাতের অন্ধকারে বীরার চোখ দিয়ে জলের ধারা নেমে আসে।"),

    ("revelations", "ট্রেনিংয়ের দিনগুলোতে বীরা আখড়ার সাধারণ নারী কুস্তিগীরদের কঠোর পরিশ্রম খুব কাছ থেকে গভীরভাবে প্রত্যক্ষ করে। সে দেখে—একটি মেয়েকে এই খেলায় নিজের পায়ের তলার মাটি খুঁজে পেতে সমাজের কত শত চোখরাঙানি, পরিবারের অসহযোগিতা আর অবর্ণনীয় শারীরিক যন্ত্রণা হাসিমুখে সহ্য করতে হয়। বীরার চোখ খুলে যায় এবং সে বুঝতে পারে কীর্তির লড়াই আর আত্মত্যাগ কতটা মহান ছিল।"),
    ("revelations", "বীরার মন থেকে সমস্ত ক্ষোভ, অহংকার আর রাগ কর্পূরের মতো উবে যায়। সে উপলব্ধি করে কীর্তি নিজের আজন্মের পরিচয় আর স্বপ্নকে বিসর্জন দিয়েছিল কেবল তাকে ও তার সংসারকে ভালোবাসত বলে। নিজের অন্ধ অহংকার আর ভুলের জন্য বীরার অন্তরে জন্ম নেয় তীব্র অনুশোচনা আর কীর্তির প্রতি গভীর শ্রদ্ধামিশ্রিত নিখাদ ভালোবাসা।"),
    ("revelations", "বাড়ি ফিরে বীরা এক আকস্মিক প্রমাণের মাধ্যমে জানতে পারে যে সেই ডিভোর্স নোটিশটি আসলে ধূর্ত চাচা রত্নম জাল সই করে পাঠিয়েছিল! রাগে কাঁপতে কাঁপতে বীরা রত্নমের কলার চেপে ধরে বাড়ি থেকে ধাক্কা মেরে রাস্তায় ফেলে দেয় এবং সাফ জানিয়ে দেয়—আজ থেকে তাদের সমস্ত পারিবারিক সম্পর্ক চিরতরে শেষ!"),
    ("revelations", "রত্নমের স্ত্রী অর্থাৎ বীরার চাচি বীরাকে ডেকে এক আবেগঘন সত্য প্রকাশ করেন। তিনি জানান—বিয়ের পরপরই কীর্তি তাকে গোপনে বলেছিল যে বীরা কোনো যৌতুক না নেওয়ায় সে বীরাকে সত্যিই মনেপ্রাণে ভালোবেসে ফেলেছে। এই কথা শোনামাত্রই বীরার বুক ভালোবাসায় ভিজে যায়, সে আর এক মুহূর্তও নষ্ট না করে কীর্তিকে ফিরিয়ে আনতে কেরালার উদ্দেশ্যে দ্রুত রওনা দেয়।"),
    ("revelations", "কেরালা পৌঁছে কীর্তির রেসলিং ক্লাবে ঢুকতেই বীরার পথ আটকে দাঁড়ায় কীর্তির লোভী ও ধূর্ত কোচ লোকেশ। এই লোকেশ ছিল এক চরম স্বার্থপর ও সুবিধাবাদী লোক, যার একমাত্র নজর ছিল কীর্তির ক্যারিয়ারের বিপুল স্পনসরশিপের কোটি কোটি টাকার ওপর। সে বীরাকে চরম অপমান করে তাড়িয়ে দেয় এবং বিষ ঢেলে মিথ্যা বলে যে কীর্তি বীরার মুখও আর দেখতে চায় না।"),
    ("revelations", "এদিকে সেই বহুল প্রতীক্ষিত টুর্নামেন্টের আর মাত্র হাতে গোনা কয়েক দিন বাকি। কীর্তি নিজেকে শারীরিক ও মানসিকভাবে প্রস্তুত করছে ন্যাশনাল চ্যাম্পিয়নশিপের জন্য। পুরো দেশের মিডিয়া এই টুর্নামেন্টের ওপর তীক্ষ্ণ নজর রেখেছে, কারণ এই ম্যাচে জয়ী হতে পারলেই সোজা আন্তর্জাতিক টুর্নামেন্টে দেশের প্রতিনিধিত্ব করার সুযোগ মিলবে।"),
    ("revelations", "ম্যাচের ঠিক আগের দিন চিকিৎসকদের নিয়মিত বাধ্যতামূলক মেডিকেল চেকআপে এক অবিশ্বাস্য ও চাঞ্চল্যকর সত্য ধরা পড়ে। রক্ত পরীক্ষার রিপোর্টে দেখা যায়—কীর্তি গর্ভবতী! সে মা হতে চলেছে! ডাক্তাররা কড়া গলায় জানিয়ে দেন—এই অবস্থায় কুস্তির রিংয়ে নামলে পেটের বাচ্চার নিশ্চিত মৃত্যু ঘটবে, এমনকি কীর্তির নিজের জীবনও চরম সংকটাপন্ন হয়ে পড়বে।"),
    ("revelations", "কিন্তু লোভী কোচ লোকেশ এই রিপোর্ট হাতে পাওয়ার পরও টাকার মোহে অন্ধ পশুর মতো আচরণ করে। সে ভালো করেই জানে কীর্তি যদি ম্যাচ না খেলে, তবে বড় বড় কর্পোরেট স্পনসররা সব চুক্তি বাতিল করবে এবং কোটি টাকার লোকসান হবে। তাই সে এই মারাত্মক সত্যটি পুরোপুরি গোপন রাখে এবং কোনো কিছু না জানিয়ে অসুস্থ ও দুর্বল কীর্তিকে জোর করে রিংয়ে নামিয়ে দেয়!"),

    ("climax", "হাজার হাজার দর্শকের গগনবিদারী গর্জনে স্টেডিয়াম মুখরিত হয়ে ওঠে। রিংয়ে পা রাখতেই শারীরিক দুর্বলতায় কীর্তির মাথা ঘুরে ওঠে। রেফারি বাঁশি বাজানোর পর প্রতিপক্ষের প্রথম ধাক্কাতেই কীর্তি নিজের ভারসাম্য পুরোপুরি হারিয়ে রিংয়ের শক্ত ম্যাটের ওপর সংজ্ঞাহীন হয়ে ধপাস করে লুটিয়ে পড়ে! পুরো স্টেডিয়ামের দর্শকরা আতঙ্কে থমকে যায়।"),
    ("climax", "দর্শকসারিতে বসে থাকা বীরা আর এক মুহূর্তও দেরি করে না। সে সমস্ত পুলিশি ব্যারিকেড আর নিরাপত্তারক্ষীদের এক ঝটকায় সরিয়ে রিংয়ে উঠে আসে এবং অচেতন কীর্তিকে নিজের কোলে পরম যত্নে তুলে নিয়ে বুকফাটা আর্তনাদে ডাক্তারদের ডাকতে থাকে। বীরা কিছুতেই মেলাতে পারে না তার সুস্থ-সবল স্ত্রীর হঠাৎ এমন কী প্রাণঘাতী অবস্থা হলো!"),
    ("climax", "ঠিক তখনই শয়তান কোচ লোকেশ রিংয়ের পাশে এসে বীরাকে তাচ্ছিল্যভরে হাসতে হাসতে বলে—আরে ও তো গর্ভবতী, পেটে বাচ্চা নিয়ে খেলতে নেমেছিল, অজ্ঞান তো হবেই! কথাটা শোনামাত্রই বীরার পায়ের তলার মাটি সরে যায় এবং মাথার ভেতর আগ্নেয়গিরি জ্বলে ওঠে। সে বুঝতে পারে—টাকার লোভে এই নরপশু কোচ তার স্ত্রী আর অনাগত সন্তানকে জেনেশুনে নিশ্চিত মৃত্যুর মুখে ঠেলে দিয়েছিল!"),
    ("climax", "বীরা অচেতন কীর্তিকে অতি সাবধানে মেডিকেল টিমের স্ট্রেচারে তুলে দেয়। এরপর সে ঘুরে দাঁড়িয়ে কোচের কলার শক্ত করে খামচে ধরে। বীরা স্টেডিয়াম কাঁপিয়ে বজ্রকণ্ঠে গর্জন করে ওঠে—আজ এই রিংয়ে কোনো নারী লড়বে না, আজ এই রিংয়ে তোর সাথে লড়ব আমি! সাবেক হেভিওয়েট কুস্তিগীর কোচ লোকেশের সাথে বীরার শুরু হয় এক মরণপণ ও রক্তক্ষয়ী কুস্তি যুদ্ধ।"),
    ("climax", "দানবাকৃতির লোকেশের একের পর এক বিধ্বংসী ঘুসি আর আঘাতে বীরা রক্তাক্ত হয়ে বারবার মাটিতে লুটিয়ে পড়ে। কিন্তু বীরার চোখে তখন ভাসছে তার অন্তঃসত্ত্বা স্ত্রীর অচেতন মুখ আর পরিবারের সম্মান। ভালোবাসার অসীম শক্তিতে বলীয়ান হয়ে বীরা আবার উঠে দাঁড়ায় এবং নিজের ট্রেনিংয়ের প্রতিটি টেকনিক কাজে লাগিয়ে সেই অতিকায় কোচকে কাঁধে তুলে রিংয়ের মেঝেতে এমন আছাড় দেয় যে লোকেশ রক্তবমি করে মাটিতে নিথর হয়ে পড়ে!"),

    ("resolution", "বিজয়োল্লাসে ফেটে পড়া স্টেডিয়ামে দাঁড়িয়ে রক্তমাখা মুখ নিয়ে বীরা মিডিয়ার সব কটি লাইভ মাইক নিজের দিকে টেনে নেয়। পুরো দেশের লাইভ ক্যামেরার সামনে দাঁড়িয়ে বীরা এক ঐতিহাসিক বক্তব্য দেয়—একটি মেয়ে নিজের স্বপ্ন পূরণ করতে গেলে তাকে পরিবারের সাথে নয়, সমাজের শত বাধার সাথে লড়তে হয়। তাদের আমাদের দাসী বানাবেন না, শুধু পাশে দাঁড়িয়ে ভালোবাসার হাতটুকু বাড়িয়ে দিন। আমি আমার স্ত্রীকে বুঝতে অনেক দেরি করেছি, আপনারা সেই ভুল করবেন না।"),
    ("resolution", "হাসপাতালের কেবিনে চোখ মেলে কীর্তি দেখে তার বিছানার পাশে বসে নিঃশব্দে কাঁদছে বীরা। বীরা কীর্তির হাত নিজের চোখের জলে ভিজিয়ে ক্ষমা চেয়ে বলে—বাচ্চা হওয়ার পর তুমি আবার এই রিংয়ে নামবে, আর সেদিন তোমাকে নিজের পরিবারের সাথে লড়তে হবে না, তুমি লড়বে প্রতিপক্ষের সাথে আর আমি আমাদের সন্তানকে কোলে নিয়ে গ্যালারি থেকে হাততালি দেব।"),
    ("resolution", "সিনেমার শেষ দৃশ্যে দেখা যায় এক জমকালো আন্তর্জাতিক কুস্তি টুর্নামেন্ট। রিংয়ের মাঝে নতুন স্বর্ণপদক আর ট্রফি উঁচিয়ে ধরছে বিজয়ী কীর্তি! আর গ্যালারিতে বসে তাদের মিষ্টি ছোট্ট মেয়েকে কোলে নিয়ে বীরা বুক ফুলিয়ে গর্বের সাথে হাততালি দিয়ে চিৎকার করছে—ওই দেখো, ওটা আমার চ্যাম্পিয়ন বউ! বন্ধুরা, এই ছিল সিনেমাটির মন ছুঁয়ে যাওয়া গল্প। ভিডিওটি ভালো লাগলে লাইক ও সাবস্ক্রাইব করে আমাদের পাশেই থাকুন, ধন্যবাদ!")
]


